var queue = new BlockingCollection<Job>(new ConcurrentQueue<Job>(), boundedCapacity: 1000);
var workers = Enumerable.Range(0, 8).Select(_ => Task.Factory.StartNew(() => {
    foreach (var job in queue.GetConsumingEnumerable()) Process(job);
}, TaskCreationOptions.LongRunning)).ToArray();
queue.Add(job);                       // blocks when the bound is reached
